OMNI.labs = [[1,"lab-stack","Lab 1: Tech Stack Explorer","Tech Stack Explorer: click each of the ten layers to see what it does and which modules teach it."],[1,"lab-click","Lab 2: Follow a click","Follow a click: animate a web request from your finger through the OS, network and internet to a data center and back."],[1,"lab-career","Lab 3: Career Path Map","Career Path Map: pick an IT role and see the recommended certification order light up."],[2,"lab-convert","Lab 1: Number Converter","Number Converter: type binary, decimal or hex, or flip 8 bit switches, and watch every base update live."],[2,"lab-units","Lab 2: Unit Calculator and Download Timer","Unit Calculator: convert bits and bytes across decimal and binary prefixes, and calculate download times."],[2,"lab-gates","Lab 3: Logic Gate Playground","Logic Gate Playground: add gates, wire them up, toggle inputs and watch outputs light; includes a ready-made half adder."],[2,"lab-text","Lab 4: Text to Binary","Text-to-Binary: type text and see each character as decimal, hex, binary and its UTF-8 bytes."],[3,"lab-timeline","Lab 1: Interactive Timeline","Interactive Timeline: a zoomable, filterable timeline of computing, networking, storage, security and data center history."],[3,"lab-then","Lab 2: Then vs Now","Then vs Now: drag across four eras to compare a computer's size, speed, memory, cost and power on a log scale."],[3,"lab-moore","Lab 3: Moore's Law Plot","Moore's Law plot: transistor counts of famous chips on a log scale with hover details and a two-year doubling line."],[4,"lab-cpu","Lab 1: CPU Simulator","CPU Simulator: a tiny 8-bit CPU with 16 bytes of RAM, animated fetch, decode and execute, preset programs and an assembly editor."],[4,"lab-pipe","Lab 2: Pipeline Visualizer","Pipeline Visualizer: watch a 5-stage pipeline, then trigger a data hazard stall or a branch misprediction flush."],[4,"lab-race","Lab 3: Memory Hierarchy Race","Memory Hierarchy Race: request data and watch it found in L1, L2, L3, RAM, SSD or disk with latency scaled so 1 CPU cycle = 1 second."],[4,"lab-boot","Lab 4: Boot Sequence Stepper","Boot Sequence Stepper: click through each boot stage with what can fail there and the matching A+ symptom."],[5,"lab-build","Lab 1: Build-a-PC","Build-a-PC: drag components onto a motherboard and get a compatibility check for socket, RAM type, PSU wattage and form factor."],[5,"lab-raid","Lab 2: RAID Simulator","RAID Simulator: pick a RAID level and disk count, see data and parity stripes, fail disks and rebuild."],[5,"lab-laser","Lab 3: Laser Printer Process","Laser Printer Process: step through processing, charging, exposing, developing, transferring, fusing and cleaning with an animated drum."],[5,"lab-ports","Lab 4: Port Identifier","Port Identifier: name connectors from drawings in quiz mode, with speeds and uses revealed."],[5,"lab-psu","Lab 5: PSU Budget Calculator","PSU Budget Calculator: add components to get total watts and a recommended power supply size."],[6,"lab-term","Lab 1: Terminal Simulator","Terminal Simulator: a Windows cmd/PowerShell and Linux bash terminal with guided missions."],[6,"lab-perm","Lab 2: Linux Permission Calculator","Linux Permission Calculator: tick r/w/x boxes and see octal and symbolic forms update, and vice versa."],[6,"lab-vm","Lab 3: Virtual Memory Visualizer","Virtual Memory Visualizer: processes request pages, RAM fills, pages swap to disk and page faults are counted."],[6,"lab-ts","Lab 4: Troubleshooting Scenario Game","Troubleshooting Scenario Game: a branching story scored against the CompTIA 7-step method."],[6,"lab-backup","Lab 5: Backup Strategy Planner","Backup Strategy Planner: choose full, incremental or differential for each day and see what a restore needs."],[7,"lab-home","Lab 1: Home Network Builder","Home Network Builder: place a router and mesh nodes on a floor plan and see a Wi-Fi heat map with walls weakening the signal."],[7,"lab-pw","Lab 2: Password Strength Tester","Password Strength Tester: estimate crack time by length and character set, computed locally, and see why length beats complexity."],[7,"lab-spec","Lab 3: Spec Sheet Decoder","Spec Sheet Decoder: hover each line of a laptop spec sheet to see what it means and whether it matters for gaming, office work or video editing."],[7,"lab-proto","Lab 4: Smart Home Protocol Picker","Smart Home Protocol Picker: answer a few questions and get the right smart home protocol with a comparison."],[8,"lab-desk","Lab 1: Help Desk Simulator","Help Desk Simulator: work through tickets by asking questions and choosing fixes, scored on time and correctness."],[8,"lab-hv","Lab 2: Hypervisor Visualizer","Hypervisor Visualizer: put VMs on a host, assign CPU and RAM, watch overcommitment, and compare Type 1 and Type 2 stacks."],[8,"lab-cr","Lab 3: Change Request Builder","Change Request Builder: fill in a change form and get feedback on missing scope, risk, rollback and approval."],[9,"lab-enc","Lab 1: Encapsulation Animator","Encapsulation Animator: type a message and watch it get wrapped layer by layer into a frame and bits, then unwrapped at the receiver. Click any header to see its fields."],[9,"lab-tcp","Lab 2: TCP Handshake Visualizer","TCP Handshake Visualizer: animate SYN, SYN-ACK and ACK with sequence numbers, toggle packet loss to see retransmission, and change the window size."],[9,"lab-osi","Lab 3: OSI Sorter","OSI Sorter: drag protocols and devices into the correct OSI layer and get a score."],[9,"lab-drill","Lab 4: Port Drill","Port Drill: a timed 60-second game for ports and protocols with a weak-spots report saved in your browser."],[10,"lab-calc","Lab 1: Subnet Calculator (Teaching Mode)","Subnet Calculator with Teaching Mode: enter an IP and prefix to see network, broadcast, host range and the mask in colored binary, with a show-me-how walkthrough."],[10,"lab-prac","Lab 2: Subnetting Practice","Subnetting Practice Generator: random subnetting problems with instant feedback and a streak counter."],[10,"lab-vlsm","Lab 3: VLSM Designer","VLSM Designer: enter host counts for several departments and see an efficient address plan drawn as blocks."],[10,"lab-dora","Lab 4: DHCP DORA and DNS Lookup","DHCP DORA and DNS Lookup Animation: step through each message between client, DHCP server, resolver, root, TLD and authoritative servers."],[10,"lab-v6","Lab 5: IPv6 Shortener","IPv6 Shortener: type a full IPv6 address and see it compressed and expanded, with the rules highlighted."],[11,"lab-tir","Lab 1: Light in a Fiber","Light in a Fiber: change the launch angle and refractive indices to see total internal reflection vs light escaping, and compare single-mode with multimode modal dispersion."],[11,"lab-spec","Lab 2: Wavelength Spectrum Explorer","Wavelength Spectrum Explorer: an interactive 400 to 1700 nm spectrum with visible light, the 850/1310/1550 windows, the O to U bands and a fiber loss curve."],[11,"lab-wdm","Lab 3: WDM Multiplexer","WDM Multiplexer Lab: choose SWDM, CWDM or DWDM, add channels, see them combined into one fiber and split back out, view the channel plan and capacity, and overlap channels to see crosstalk."],[11,"lab-budget","Lab 4: Link Loss Budget Calculator","Link Loss Budget Calculator: choose fiber type, wavelength, length, connectors and splices, then compare total loss to a transceiver budget with a pass/fail meter."],[11,"lab-pin","Lab 5: Copper Pinout Builder","Copper Pinout Builder: drag the 8 colored wires into T568A or T568B order, then test as straight-through or crossover."],[11,"lab-mod","Lab 6: Modulation Viewer (NRZ vs PAM4)","Modulation Viewer: see a bit stream as NRZ (2 levels) and PAM4 (4 levels) waveforms and how PAM4 doubles bits per symbol."],[12,"lab-switch","Lab 1: Switch Learning Simulator","Switch Learning Simulator: send frames between hosts, watch MAC tables fill, unknown destinations flood, VLANs isolate traffic and a trunk carry tagged frames."],[12,"lab-stp","Lab 2: Spanning Tree Visualizer","Spanning Tree Visualizer: elect the root bridge, see root, designated and blocked ports, change priorities and cut links to watch reconvergence."],[12,"lab-route","Lab 3: Routing Table Lab","Routing Table Lab: compare static routes with a link-state protocol, trace a packet hop by hop, and break links to watch the path change."],[12,"lab-nat","Lab 4: NAT/PAT Translator","NAT/PAT Translator: watch inside and outside addresses and port mappings update as several inside hosts browse the web."],[12,"lab-qos","Lab 5: QoS Queue Visualizer","QoS Queue Visualizer: mixed voice, video and bulk traffic share a congested link; toggle QoS and watch voice delay and jitter drop."]];
